-- =====================================================================
-- SQL INSERT: 16 SKILL THẦN TRANG CHỦ ĐỘNG (ACTIVE ATTACK SKILLS)
-- Bảng dữ liệu chính thức game Hải Tặc Tí Hon
-- =====================================================================

DELETE FROM `skill` WHERE (`id` BETWEEN 4001 AND 4016 OR `id_index` BETWEEN 4001 AND 4016);

